package com.bank.portal.web;
import com.bank.portal.service.OnboardingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/account-requests") @RequiredArgsConstructor public class OnboardingController {private final OnboardingService service; @PostMapping public OnboardingRequestView submit(@Valid @RequestBody OnboardingRequestInput r){return service.submit(r);}@GetMapping @PreAuthorize("hasRole('STAFF')") public List<OnboardingRequestView> pending(){return service.pending();}@PatchMapping("/{id}") @PreAuthorize("hasRole('STAFF')") public OnboardingRequestView review(@PathVariable Long id,@Valid @RequestBody OnboardingReviewInput r,Authentication a){return service.review(id,r,a.getName());}}
